import unittest

from hourglass.models import Span
from hourglass.rounding import label_spans


class LabelTests(unittest.TestCase):
    def test_exact_edges_are_kept(self):
        self.assertEqual(
            label_spans([Span(540, 1035)], 15),
            ["09:00-17:15 (8h 15m)"],
        )

    def test_edges_snap_to_nearest(self):
        self.assertEqual(
            label_spans([Span(543, 1030)], 15),
            ["09:00-17:15 (8h 15m)"],
        )

    def test_tie_rounds_up(self):
        self.assertEqual(
            label_spans([Span(547, 1050)], 15),
            ["09:00-17:30 (8h 30m)"][:0]
            or ["09:00-17:30 (8h 30m)"],
        )

    def test_many_spans_keep_order(self):
        labels = label_spans([Span(0, 60), Span(600, 690)], 30)
        self.assertEqual(
            labels, ["00:00-01:00 (1h 0m)", "10:00-11:30 (1h 30m)"]
        )

    def test_empty_list(self):
        self.assertEqual(label_spans([], 15), [])

    def test_end_of_day(self):
        self.assertEqual(
            label_spans([Span(1400, 1440)], 20),
            ["23:20-24:00 (0h 40m)"],
        )


class StepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 90):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    label_spans([Span(0, 60)], step)

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            label_spans([Span(541, 549)], 60)
